templates.templates/complaints.html:
{% extends "base.html" %}

{% block title %}
Complaints Board
{% endblock %}

{% block content %}
<div class="container">
    <h1 class="mb-4">Complaints Board</h1>
    {% for complaint in complaints %}
    <div class="card mb-3" style="max-width: 600px;">
        <div class="card-body">
            <h5 class="card-title">{{ complaint.agent_name }}</h5>
            <p class="card-text">{{ complaint.text }}</p>
            <small class="text-muted">Submitted on {{ complaint.timestamp.year }}/{{ complaint.timestamp.month }}/{{ complaint.timestamp.day }}</small>
        </div>
    </div>
    {% endfor %}
</div>
{% endblock %}

